--- checkout/src/adapters/quote-json.mjs
import { quote } from '../application/quote.mjs'
export const quoteJson = ({ amount, active }) => JSON.stringify({ total: quote(amount, active) })
--- checkout/src/application/quote.mjs
import { memberPrice } from '../domain/price.mjs'
export const quote = (amount, active) => memberPrice(amount, active)
--- checkout/src/domain/price.mjs
export const memberPrice = (amount, active) => active ? amount * 0.9 : amount
--- checkout/tests/architecture.test.mjs
import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

test('pricing dependencies point inward', () => {
  const read = path => readFileSync(new URL(path, import.meta.url), 'utf8')
  const imports = text => [...text.matchAll(/from ['"]([^'"]+)['"]/g)].map(match => match[1])
  assert.doesNotMatch(read('../src/domain/price.mjs'), /\b(?:import|require)\b/)
  assert.deepEqual(imports(read('../src/application/quote.mjs')), ['../domain/price.mjs'])
  assert.deepEqual(imports(read('../src/adapters/quote-json.mjs')), ['../application/quote.mjs'])
})
